const o=["admin","administrator","root","system","staff","support","help","official","openartshow","oas","ayamo","moderator","mod","owner","null","undefined","anonymous","guest","me","you","관리자","운영자","운영팀","공식","고객센터","오픈아트쇼","아야모"];function r(e){return e.toLowerCase().replace(/_/g,"").replace(/0/g,"o").replace(/1/g,"i").replace(/3/g,"e").replace(/4/g,"a").replace(/5/g,"s").replace(/7/g,"t")}function a(e){return o.includes(r(e))}export{a as i};
